diff --git a/lib/rules/hue-degree-notation/index.mjs b/lib/rules/hue-degree-notation/index.mjs
index 42a1bc454b..9bca1f83e9 100644
--- a/lib/rules/hue-degree-notation/index.mjs
+++ b/lib/rules/hue-degree-notation/index.mjs
@@ -100,12 +100,17 @@ function findHue(node) {
 	const args = node.nodes.filter(({ type }) => type === 'word' || type === 'function');
 	const value = node.value.toLowerCase();

+	// If using relative color syntax, for instance `oklch(from red l c h)`, the
+	// channels start from the 2nd value.
+	const isRelativeColor = args[0]?.value.toLowerCase() === 'from';
+	const offset = isRelativeColor ? 2 : 0;
+
 	if (HUE_FIRST_ARG_FUNCS.includes(value)) {
-		return args[0];
+		return args[0 + offset];
 	}

 	if (HUE_THIRD_ARG_FUNCS.includes(value)) {
-		return args[2];
+		return args[2 + offset];
 	}

 	return undefined;
